import { defineCollection } from "astro:content";
import { metaLoader, pageLoader } from "@fumadocs/astro/loaders";
import { z } from "astro/zod";
import { pageSchema } from "fumadocs-core/source/schema";

/**
 * Two spaces, two collections, two meta collections.
 *
 * The handbook's `_meta.json` files are generated by `scripts/sync-handbook.mjs` and the developer
 * pages' by `scripts/sync-docs.mjs`, so the sidebar order is a property of the files rather than
 * of this configuration. `lastModified` is the one field the portal sorts on.
 */
const page = pageSchema.extend({
  lastModified: z.string().optional(),
});

export const collections = {
  docs: defineCollection({ loader: pageLoader("docs"), schema: page }),
  docsMeta: defineCollection({ loader: metaLoader("docs") }),
  handbook: defineCollection({ loader: pageLoader("handbook"), schema: page }),
  handbookMeta: defineCollection({ loader: metaLoader("handbook") }),
};
